  module: "马克思主义基本原理",
  difficulty: 2,
  stem: "空想社会主义产生于16世纪初期，到19世纪上半叶达到顶峰。空想社会主义的发展经历了三个阶段，即16 - 17世纪的早期空想社会主义、18世纪的空想平均共产主义、19世纪初期批判的空想社会主义。与之对应的资本主义生产方式发展所经历的阶段是",
