  explanation: "道德属于上层建筑的范畴，是一种特殊的社会意识形态。道德是以善恶为评价方式，主要依靠社会舆论、传统习俗和内心信念来发挥作用的行为规范的总和。A、B、C正确。国家强制性是法律规范区别于其他社会规范的一个重要特征。作为一种调整人与人、人与社会、人与自然以及人与自身之间关系的特殊的行为规范，道德与法律规范、政治规范的不同之处在于，它是用善恶标准去评价，依靠社会舆论、传统习俗、内心信念来维持的，因此是一种非强制性的规范。D错误。\n点拨道德的调节功能是指道德通过评价等方式指导和纠正人们的行为和实践活动、协调社会关系和人际关系的功效与能力。道德评价是道德调节的主要形式，社会舆论、传统习俗和人们的内心信念是道德调节所赖以发挥作用的力量。",
