  id: "q-x8-s3-17",
  type: "multi",
  module: "马克思主义基本原理",
  difficulty: 2,
  stem: "虚拟电厂是一种通过先进信息通信技术和软件系统，聚合分布式能源资源，实现协调优化以参与电力市场和电网运行的智能能源管理系统。虚拟电厂看不见、摸不着，没有成片的厂房，但能聚合分布式电源、可调节负荷、储能等各类分散资源，协同参与电力系统优化和电力市场交易，对增强电力保供能力、促进新能源消纳等具有重要作用。虚拟电厂看不见、摸不着，却能通过聚合分布式能源资源起到重要作用，这说明",
