  explanation: "实事求是是毛泽东思想的基本点，是毛泽东思想的精髓。这条思想路线由毛泽东确立于民主革命时期。毛泽东向来反对离开中国社会和中国革命的实际去研究马克思主义。1930年，他在《反对本本主义》中强调调查研究是一切工作的第一步，提出了“没有调查，没有发言权”的著名论断。为了统一全党思想并为制定新民主主义革命的总路线奠定思想基础，毛泽东在延安整风期间又从思想路线的角度，不仅系统阐述了坚持实事求是的重要性，而且对实事求是的科学含义作了马克思主义的界定。毛泽东还把实事求是形象地比喻为“有的放矢”，强调我们要坚持用马克思主义之“矢”去射中国革命之“的”。经过延安整风和党的七大，实事求是的思想路线在全党得到了确立。A、B正确。\n毛泽东在新民主主义革命时期领导我们党克服了党内曾经盛行的把马克思主义教条化、把共产国际决议和苏联经验神圣化的错误倾向，在全党确立了实事求是的思想路线，由此保证了新民主主义革命和社会主义改造的胜利。然而，党没能始终如一坚持这条思想路线，在社会主义建设道路的探索中出现了曲折。邓小平指出：“一个党，一个国家，一个民族，如果一切从本本出发，思想僵化，迷信盛行，那它就不能前进，它的生机就停止了，就要亡党亡国。”C是邓小平的观点，不符合题意。“不唯上、不唯书、只唯实，交换、比较、反复”是陈云提出的，D不符合题意。",
