  type: "multi",
  module: "形势与政策",
  difficulty: 2,
  stem: "当前，全球气候治理体系面临深刻变革，绿色低碳发展已成为国际社会的普遍共识和共同追求。实现碳达峰碳中和，是以习近平同志为核心的党中央统筹国内国际两个大局作出的重大战略决策，彰显出中国推动构建人类命运共同体的大国担当。减碳，不是别人让我们做，而是我们自己必须要做。减碳有利于",
