  difficulty: 2,
  stem: "2025年9月12日，十四届全国人大常委会第十七次会议表决通过《法治宣传教育法》。制定《法治宣传教育法》是夯实全面依法治国社会基础的迫切要求。通过国家立法，在全社会弘扬社会主义法治精神、培育法治信仰、传播法律知识，使尊法学法守法用法成为全体人民的共同追求，让法治成为全民思维方式和行为习惯，为全面建设社会主义现代化国家营造良好法治环境。法治思维是一种",
