  difficulty: 2,
  stem: "“谷子”是英文单词“goods（商品）”的谐音，泛指由漫画、动画、游戏等领域版权作品衍生出来的周边产品，例如徽章、角色立牌、色纸、小挂件等。相关数据显示，2023年中国“谷子经济”市场规模1201亿元，2024年迅速飙升至1689亿元，预计2029年整体市场规模有望达3089亿元。“谷子经济”火爆的背后蕴藏着青年消费者对优秀动漫、动画等文化作品的认同，折射出从“实用”到“情绪价值”的消费需求转变。年轻人情绪消费的崛起并非偶然，其本质是物质需求饱和后，精神需求升级的结果。年轻人愿意为“情绪”买单，有收入水平提高的原因，也是放松精神、休闲娱乐的现实需要。虽然有人无法理解年轻人对“谷子”的喜爱，但也不得不承认，“情绪价值”也是一种价值。从“实用”到“情绪价值”的消费需求转变说明",
