  stem: "20世纪50年代；亚洲、非洲、拉丁美洲的广大地区出现民族解放运动的高潮。中国在支持民族解放运动中同广大发展中国家建立了友好关系。在广大发展中国家支持下，1971年10月25日，第26届联大通过2758号决议，“决定恢复中华人民共和国的一切权利，承认中华人民共和国政府的代表为中国在联合国组织的唯一合法代表并立即把蒋介石的代表从它在联合国组织及其所属一切机构中所非法占据的席位上驱逐出去”。联大第2758号决议",
