  explanation: "1971年10月25日，第26届联合国大会以压倒性多数通过第2758号决议，“决定恢复中华人民共和国的一切权利，承认中华人民共和国政府的代表为中国在联合国组织的唯一合法代表并立即把蒋介石的代表从它在联合国组织及其所属一切机构中所非法占据的席位上驱逐出去”。该决议从政治上、法律上和程序上干净彻底地解决了包括台湾在内全中国在联合国的代表权问题。它的合法性、有效性、权威性不容挑战。一个中国原则是联大第2758号决议的前提和基础，联大第2758号决议郑重确认、充分体现了一个中国原则，明确了世界上只有一个中国，中华人民共和国政府是代表包括台湾在内全中国的唯一合法代表，不存在“两个中国”“一中一台”。联大第2758号决议具有广泛而权威的法律效力，为联合国系统及机构妥善处理台湾问题提供了权威依据。A、C、D正确。80年前的历史铁证早已充分证明，台湾光复既是中国人民抗日战争胜利的重要成果，也是二战胜利成果和战后国际秩序的重要组成部分。台湾在法律上、事实上都已经彻底回归中国，上承《中国对日宣战布告》《开罗宣言》《波茨坦公告》《日本投降书》，下启联大第2758号决议，这一系列国际法文件环环相扣，共同构成了台湾是中国一部分的国际法证据链。B正确。",
