  module: "马克思主义基本原理",
  difficulty: 1,
  stem: "数字孪生水利是指通过人工智能、5G、大模型等技术，把现实世界的自然水系和水利工程“搬”到互联网上，实现虚实物体之间仿真模拟，进而开展精准预报、超前预警、快速预演、制定预案。近年来，水利部门先行完成了94项数字孪生水利建设任务。三峡水利枢纽工程，大坝、大江和连绵群山一一映射到虚拟空间，参数变动，为库容调度、冲淤提供精准方案；南水北调中线工程.电子围栏、远程控制系统护佑一渠清水北上，全天候监测1400多公里渠道⋯⋯将现实水利工程“搬”到互联网上构建数字孪生体，开展精准预演，这一做法说明",
  options: [
    {
      "key": "A",
      "text": "人的意识不仅反映客观世界，并且创造客观世界"
    },
    {
      "key": "B",
      "text": "物质与意识何者为第一性的问题在虚拟实践中已经失去意义"
    },
    {
      "key": "C",
      "text": "入类可以凭借技术手段创造独立的虚拟世界，使其完全脱离物质世界的束缚"
    },
    {
      "key": "D",
      "text": "人们的思想、理论、计划和方案在实践中总是能够得到预想的结果"
    }
  ],
  answerKey: "A",
  explanation: "意识的能动性突出地表现在对于客观世界的改造上。意识的能动性不限于从实践中形成一定的思想，形成活动的目的、计划、方法等观念的东西，更重要的是以这些观念的东西为指导，通过实践把“观念地存在”着的模型、蓝图实现出来，变为客观现实。这就是列宁所说的：“世界不会满足人，人决心以自己的行动来改变世界。”“人的意识不仅反映客观世界，并且创造客观世界。”数字孪生体是意识对物质世界的能动反映和创造性构建，A正确。\n对哲学基本问题的回答是解决其他一切哲学问题的前提和基础。只有科学解决存在和思维的关系问题，才能正确认识世界的本质和把握世界发展的规律。B错误。世界统一于物质，虚拟世界不能脱离物质世界，C错误。人们在实践中得来的思想、理论、计划和方案毫无改变地实现的情况很少。许多时候，经过多次失败，不断纠错，才能实现主客观的统一，在实践中得到预想的结果。D错误。\n点拨近几年真题多次出现了引用马克思等经典作家原话作为正确选项的情况。例如：2025年第2题正确选项B“人体解剖对于猴体解剖是一把钥匙”，2025年第21题正确选项D“资产阶级不对生产工具和生产关系进行革命就不能生存”，2024年第18题正确选项A“观念的东西不外是移入人脑并经过人脑改造过的物质的东西而已”等。因此，同学们应加强这方面的知识储备。本题的A 选项引用了列宁的原话（教材中也引用了这句话），也是为了让同学们了解一下这一说法。",
