  answerKey: "B",
  explanation: "在资本主义制度下，工人的工资是劳动力的价值或价格，这是资本主义工资的本质。B正确。从数量上讲，资本主义工资支付的仅仅是工人必要劳动时间内创造的价值量（劳动力商品的价值），而剩余劳动时间内创造的剩余价值是被资本家无偿占有的。A、D错误。不变资本是以生产资料形态存在的资本，可变资本是用来购买劳动力的那部分资本。C错误。",
