  difficulty: 1,
  stem: "随着资本输出的不断增加和垄断资本势力范围的迅速扩大，各国之间的经济联系日益密切，同时，彼此间的竞争更为激烈，矛盾和冲突也更为突出。在这一背景下，各资本主义国家的垄断组织，通过订立协议建立起国际垄断资本的联盟，即国际垄断同盟，以便在世界范围形成垄断，并在经济上瓜分世界。当代国际垄断同盟的主要形式是",
