  module: "马克思主义基本原理",
  difficulty: 2,
  stem: "从外卖诗人王计兵到“沂蒙二姐”吕玉霞，再到由各行各业劳动者构成的东莞新大众文艺群体⋯⋯以“素人写作”为代表的新大众文艺现象，展现了这样一个图景- - 普通人不再只是被书写的客体，也是执笔的创作主体。新大众文艺背后的动力，源于时代发展与社会心态的共振。快递员王计兵的诗集《赶时间的人》销量破10万册，草根作家单小花的散文《洋芋，洋芋》获孙犁散文奖，吕玉霞的“乡土诗歌”在全网获近千万点赞⋯⋯他们的写作沾泥土、带露珠，能够引发更多情感共鸣。有评论指出，“素人写作”戳中了某种时代刚需，人们更愿意为身边的奋斗鼓掌，更喜欢“同频共振的心跳”。新大众文艺正在回应“何为文学”“谁来书写”的时代命题。当建筑工地的敲打声、厨房的翻炒声、键盘的敲击声都成为时代的韵脚，我们见证的不仅是文学创作群体的扩容，更是文化活力的激荡。“素人写作”作为新大众文艺现象，其产生和走红背后蕴含着深刻的历史唯物主义原理，对此理解正确的是",
