  stem: "（1）万隆会议已经过去70年了，今天我们为什么还要弘扬万隆精神？（或：如何认识万隆精神的时代价值？（2）“全球南方”应如何弘扬万隆精神，推动构建人类命运共同体？",
  material: {
    title: "材料",
    paragraphs: [
      "材料 1\n1955年4月18日至24日，第一届亚非会议在印度尼西亚万隆召开，这次会议也被称为万隆会议。70年来，万隆会议倡导的尊重主权、和平共处、团结合作等原则，以及形成的团结、友谊、合作的万隆精神，为亚非国家独立自主发展提供指引，激励全球南方国家联合自强，在地区和国际事务中发挥着越来越重要的作用。",
      "万隆会议是亚非国家在没有西方殖民国家参与的情况下第一次自主召开的国际会议，是亚非民族解放运动蓬勃发展的重要里程碑。习近平主席2015年在亚非领导人会议上发表讲话指出：“会议在和平共处五项原则基础上，提出处理国家间关系的十项原则，为推动国际关系朝着正确方向发展，为推动亚非合作、南南合作，为促进南北合作，发挥了重大历史性作用。因此，万隆会议是亚非人民团结合作的一个里程碑。”摘编自《人民日报》（2025年4月30日）",
      "材料 2\n今年是中国人民抗日战争暨世界反法西斯战争胜利80周年、联合国成立80周年，也是万隆会议召开70周年。双方要密切在国际和地区事务中的合作，弘扬和平共处五项原则和万隆精神，共同维护以联合国为核心的国际体系和以国际法为基础的国际秩序，推动全球治理朝着更加公正合理的方向发展。摘自习近平《让中马友谊之船驶向更加美好的未来》",
      "材料 3\n在万隆会议上，新生的亚非国家团结起来坚定捍卫国家独立，彰显了南方国家自力更生、合作互助的精神气质，成为南方国家集体身份认同的历史起点，为全球南方追求独立自主、平等互利的国际关系理念提供了历史范本。",
      "推动构建人类命运共同体，是新时代对万隆精神的伟大传承和发扬。随着推动构建人类命运共同体从中国倡议扩大为国际共识，从美好愿景转化为丰富实践，弘扬万隆精神也必将有力推动世界走向和平、安全、繁荣、进步的光明前景。摘编自《光明日报》（2025年4月23日）"
    ]
  },
  answerPoints: [
    "（1）2025年是万隆会议召开70 周年。70年前，万隆精神有力促进了亚非国家的团结与合作，推动了世界范围民族解放运动的蓬勃发展，开启了南南合作的历史进程。70年后的今天，“全球南方”正在群体性崛起，国际力量对比正在发生深刻调整，但单边主义、保护主义、霸凌主义显著上升，世界和平赤字、发展赤字、安全赤字、治理赤字不断涌现。站在新的历史起点上，弘扬万隆精神，既是顺应国际关系发展正确方向和时代潮流的必然要求，也是应对当前全球性挑战、共建更加美好世界的客观需要。随着全球南方的崛起，亚非拉国家正在加强团结合作，努力改变不合理的国际政治经济秩序和国际格局，我们比以往任何时候都更加需要弘扬万隆精神，更加需要朝着构建人类命运共同体的崇高目标不懈努力。",
    "（2）当今时代，全球南方卓然壮大，在巩固独立成果的同时致力于赋能世界和平稳定，促进各国共同繁荣，构建合作共赢的新型国际关系，推动国际秩序更加公正合理，成为弘扬万隆精神的中坚力量。推动构建人类命运共同体，是新时代对万隆精神的伟大传承和发扬。“全球南方”要做维护和平的稳定力量、开放发展的中坚力量、全球治理的建设力量、文明互鉴的促进力量，推动构建人类命运共同体。"
  ],
  explanation: "（1）2025年是万隆会议召开70 周年。70年前，万隆精神有力促进了亚非国家的团结与合作，推动了世界范围民族解放运动的蓬勃发展，开启了南南合作的历史进程。70年后的今天，“全球南方”正在群体性崛起，国际力量对比正在发生深刻调整，但单边主义、保护主义、霸凌主义显著上升，世界和平赤字、发展赤字、安全赤字、治理赤字不断涌现。站在新的历史起点上，弘扬万隆精神，既是顺应国际关系发展正确方向和时代潮流的必然要求，也是应对当前全球性挑战、共建更加美好世界的客观需要。随着全球南方的崛起，亚非拉国家正在加强团结合作，努力改变不合理的国际政治经济秩序和国际格局，我们比以往任何时候都更加需要弘扬万隆精神，更加需要朝着构建人类命运共同体的崇高目标不懈努力。\n（2）当今时代，全球南方卓然壮大，在巩固独立成果的同时致力于赋能世界和平稳定，促进各国共同繁荣，构建合作共赢的新型国际关系，推动国际秩序更加公正合理，成为弘扬万隆精神的中坚力量。推动构建人类命运共同体，是新时代对万隆精神的伟大传承和发扬。“全球南方”要做维护和平的稳定力量、开放发展的中坚力量、全球治理的建设力量、文明互鉴的促进力量，推动构建人类命运共同体。",
