  difficulty: 1,
  stem: "1947年10月10日，中国人民解放军总部发表宣言，提出“打倒蒋介石，解放全中国”的口号，极大鼓舞了解放军全体指战员和全国人民的斗志。同年12月，中共中央在陕北米脂县杨家沟召开会议，制定了夺取全国胜利的行动纲领。为打败蒋介石、建立新中国奠定了深厚的群众基础的是",
