  difficulty: 1,
  stem: "《民法典》是新中国成立以来第一部以“法典”命名的法律，被誉为“保障民事权利的宣言书”。权利保障主要是指对公民权利的法律保障，具体包括宪法保障、立法保障、行政保障和司法保障。权利保障的关键环节是",
