  stem: "新民主主义革命时期，中国工会团结动员广大工人群众以大无畏革命精神，奋勇投身反对帝国主义、封建主义、官僚资本主义的革命洪流，前赴后继、浴血奋战，为实现民族独立和人民解放、建立新中国作出了重要贡献。中国工人运动史上持续时间最长的一次政治大罢工是",
