  module: "毛泽东思想和中国特色社会主义理论体系",
  difficulty: 3,
  stem: "（1）如何理解“适应形势任务的发展变化，平安中国建设只能加强，不能削弱”？（2）为什么要“进一步树立发展是硬道理、安全也是硬道理的理念”？",
  material: {
    title: "材料",
    paragraphs: [
      "习近平在听取讲解和讨论后发表重要讲话。他指出，党的十八大以来，党中央不断完善国家安全领导体制和法治体系、战略体系、政策体系，完善社会治理体系，强化社会治安整体防控，着力提高公共安全治理水平，坚决维护国家主权、安全、发展利益，成功续写了经济快速发展和社会长期稳定“两大奇迹”新篇章。适应形势任务的发展变化，平安中国建设只能加强，不能削弱。",
      "习近平强调，总体国家安全观是建设更高水平平安中国的重要遵循，必须坚定不移贯彻。各级党委和政府要坚持系统思维，进一步树立发展是硬道理、安全也是硬道理的理念，在工作中自觉把发展和安全统一起来，共同谋划、一体部署、相互促进。要坚持全国一盘棋、上下齐发力，通过抓好一地一域一业的安全为国家整体安全创造条件，通过及时有效解决一个个安全问题为国家长治久安筑牢根基。",
      "习近平指出，平安中国建设为了人民，也依靠人民。要不断增进民生福祉，扎实推进共同富裕，切实维护人民群众合法权益，维护社会公平正义。要完善社会治理体系、健全社会工作体制机制，建设人人有责、人人尽责、人人享有的社会治理共同体。要培育自尊自信、理性平和、积极向上的社会心态，弘扬锐意进取、甘于奉献、崇尚法治、文明礼让的时代新风。",
      "习近平强调，防范化解各类风险是平安中国建设的一项重要任务。要把捍卫国家政治安全摆在首位，坚定维护国家政权安全、制度安全、意识形态安全。要完善公共安全体系，推动公共安全治理模式向事前预防转型，加强防灾减灾救灾、安全生产、食品药品安全、网络安全、人工智能安全等方面工作。要着力防范重点领域风险。",
      "习近平指出，建设更高水平平安中国，必须强化社会治安整体防控。要把专项治理和系统治理、依法治理、综合治理、源头治理结合起来，发展壮大群防群治力量，筑起真正的铜墙铁壁。要坚持和发展新时代“枫桥经验”，推进信访工作法治化，及时有效化解各种矛盾纠纷。摘编自《人民日报》（2025年3月2日）"
    ]
  },
  answerPoints: [
    "（1）建设更高水平平安中国，是积极应对各类风险挑战，服务保障强国建设、民族复兴伟业的客观需要；是有效满足人民日益增长的美好生活需要的重要举措；是谱写“中国之治”新篇章的迫切需要。",
    "（2）统筹发展和安全，是党和国家的一项基础性工作，是我们党治国理政的一个重大原则。\n第一，发展和安全是两件大事。发展解决的是动力问题，是推动国家和民族赓续绵延的根本支撑；安全解决的是保障问题，是确保国家和民族行稳致远的坚强柱石。\n第二，发展具有基础性、根本性，是解决安全问题的总钥匙，发展就是最大的安全。安全是发展的条件和保障，没有国家安全，发展取得的成果也可能毁于一旦。国家安全是中国式现代化行稳致远的重要基础。\n第三，发展和安全是一体之两翼、驱动之双轮，必须同步推进，以发展促安全、以安全保发展，实现高质量发展和高水平安全良性互动，切实保障国家长治久安，确保中华民族伟大复兴进程不被迟滞甚至中断，胜利实现全面建成社会主义现代化强国目标。"
  ],
  explanation: "（1）建设更高水平平安中国，是积极应对各类风险挑战，服务保障强国建设、民族复兴伟业的客观需要；是有效满足人民日益增长的美好生活需要的重要举措；是谱写“中国之治”新篇章的迫切需要。\n（2）统筹发展和安全，是党和国家的一项基础性工作，是我们党治国理政的一个重大原则。\n第一，发展和安全是两件大事。发展解决的是动力问题，是推动国家和民族赓续绵延的根本支撑；安全解决的是保障问题，是确保国家和民族行稳致远的坚强柱石。\n第二，发展具有基础性、根本性，是解决安全问题的总钥匙，发展就是最大的安全。安全是发展的条件和保障，没有国家安全，发展取得的成果也可能毁于一旦。国家安全是中国式现代化行稳致远的重要基础。\n第三，发展和安全是一体之两翼、驱动之双轮，必须同步推进，以发展促安全、以安全保发展，实现高质量发展和高水平安全良性互动，切实保障国家长治久安，确保中华民族伟大复兴进程不被迟滞甚至中断，胜利实现全面建成社会主义现代化强国目标。",
