    "（2）普惠的经济全球化，就是做大并分好经济发展的“蛋糕”，让不同国家、不同阶层、不同人群都能参与并享有经济社会发展的成果，妥善解决国家间和各国内部发展失衡问题，实现共同发展、共同繁荣。\n包容的经济全球化，就是支持各国走出符合自身国情的发展道路，不搞发展模式的单一化，摒弃损人利已的单边主义、保护主义，维护全球产业链供应链的稳定畅通，保持全球经济增长活力与动力。\n普惠包容的经济全球化是人心所向、人间正道。中国倡导并推动普惠包容的经济全球化，有着现实针对性和战略指导性，将引领经济全球化正确方向，为解决当今世界面临的一系列重大问题和挑战贡献中国智慧，为构建人类命运共同体提供坚实依托，具有重要深远意义。"
