  stem: "信息传递是人类生存发展的基础。从最初的肢体语言到驿站传书，再到承载海量数据的互联网，信息一直是人类社会不可或缺的存在。作为地球上重要的“居民”，自然界里的植物是否也存在信息交换呢？答案是肯定的。比如番茄会在受到伤害时群发“茉莉味”的信号，让周边的番茄秒变“苦瓜脸”。这套由挥发性气味小分子编织的“空气互联网”，如同自然界的“聊天记录”传递信息，让不会移动的植物们实现了跨时空的生存协作。随着化学生态学的发展，人类正逐步解码植物王国的“社交密码”，或许有一天，人类能够精准识别植物间的语言，听懂它们的“悄悄话”、了解它们成长丰产的需求，进而为它们遮风挡雨。人类对植物间信息交换的解码说明",
