  difficulty: 1,
  stem: "习近平指出：“中国式现代化，是中国共产党领导的社会主义现代化，既有各国现代化的共同特征，更有基于自己国情的中国特色。”党的二十大集中概括了中国式现代化五个方面的中国特色，深刻揭示了中国式现代化的科学内涵，这是理论概括，也是实践要求。关于中国式现代化，以下说法正确的是①人口规模巨大的现代化是中国式现代化的显著特征②全体人民共同富裕的现代化是中国式现代化的本质特征③既要物质富足、也要精神富有，是中国式现代化的崇高追求④促进人与自然和谐共生，是中国式现代化区别于西方现代化的显著标志",
