  explanation: "马克思劳动价值论的理论意义和实践意义：第一，马克思劳动价值论扬弃了英国古典政治经济学的观点，为剩余价值理论的创立奠定了基础。第二，马克思劳动价值论揭示了私有制条件下商品经济的基本矛盾，为从物与物的关系背后揭示人与人的关系提供了理论依据。第三，马克思劳动价值论揭示了商品经济的一般规律，对理解社会主义市场经济具有指导意义。B、C、D正确。在马克思之前，英国古典政治经济学的代表人物亚当·斯密已经认识到了商品的二因素，提出了劳动创造价值的观点。马克思在继承英国古典政治经济学劳动创造价值理论的同时，创立了劳动二重性理论，第一次确定了什么样的劳动形成价值、为什么形成价值以及怎样形成价值，阐明了具体劳动和抽象劳动在商品价值形成中的不同作用，从而为揭示剩余价值的真正来源、创立剩余价值理论奠定了基础。A错误。",
